// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Liveness probe
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReady Readiness probe (checks the database)
	// (GET /readyz)
	GetReady(ctx context.Context, request GetReadyRequestObject) (GetReadyResponseObject, error)
	// GetFixtureRuns Audit trail of every computation of a fixture
	// (GET /v1/fixtures/{fixtureId}/runs)
	GetFixtureRuns(ctx context.Context, request GetFixtureRunsRequestObject) (GetFixtureRunsResponseObject, error)
	// GetFixtureScores Voti and fantavoti for every player of a fixture
	// (GET /v1/fixtures/{fixtureId}/scores)
	GetFixtureScores(ctx context.Context, request GetFixtureScoresRequestObject) (GetFixtureScoresResponseObject, error)
	// GetPlayer Get a player
	// (GET /v1/players/{playerId})
	GetPlayer(ctx context.Context, request GetPlayerRequestObject) (GetPlayerResponseObject, error)
	// ListRuleSets List every published rule set version
	// (GET /v1/rulesets)
	ListRuleSets(ctx context.Context, request ListRuleSetsRequestObject) (ListRuleSetsResponseObject, error)
	// GetRuleSet Get one rule set version, as published
	// (GET /v1/rulesets/{rulesetId}/versions/{version})
	GetRuleSet(ctx context.Context, request GetRuleSetRequestObject) (GetRuleSetResponseObject, error)
	// ListSeasons List seasons
	// (GET /v1/seasons)
	ListSeasons(ctx context.Context, request ListSeasonsRequestObject) (ListSeasonsResponseObject, error)
	// ListMatchdays List a season's matchdays and fixtures
	// (GET /v1/seasons/{seasonId}/matchdays)
	ListMatchdays(ctx context.Context, request ListMatchdaysRequestObject) (ListMatchdaysResponseObject, error)
	// GetMatchdayScores Voti and fantavoti for every player of a matchday
	// (GET /v1/seasons/{seasonId}/matchdays/{number}/scores)
	GetMatchdayScores(ctx context.Context, request GetMatchdayScoresRequestObject) (GetMatchdayScoresResponseObject, error)
	// GetPlayerSeasonScores A player's voti and fantavoti across a season
	// (GET /v1/seasons/{seasonId}/players/{playerId}/scores)
	GetPlayerSeasonScores(ctx context.Context, request GetPlayerSeasonScoresRequestObject) (GetPlayerSeasonScoresResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

